def max_run_uppercase(s: str) -> int:
    """Return the length of the longest consecutive run of uppercase letters in s."""
    if not s:
        return 0

    current = 0
    best = 0

    for ch in s:
        if 'A' <= ch <= 'Z':          # or use str.isupper() but this is explicit about ASCII A-Z
            current += 1
            if current > best:
                best = current
        else:
            current = 0

    return best

# Example usage and assertion
if __name__ == "__main__":
    assert max_run_uppercase('GeMKSForGERksISBESt') == 5

